import{_ as t}from"./chunks/flaky-detection.CN9mtzEz.js";import{_ as a,o as s,c as r,a6 as o}from"./chunks/framework.CCKCzdWs.js";const y=JSON.parse('{"title":"Cut costly flakiness","titleTemplate":"Flaky Playwright suite: :title | Piwi","description":"One afternoon to make an unreliable suite trustworthy: fix the flaky tests that cost the most, one root cause at a time, and quarantine the rest.","frontmatter":{"title":"Cut costly flakiness","titleTemplate":"Flaky Playwright suite: :title | Piwi","description":"One afternoon to make an unreliable suite trustworthy: fix the flaky tests that cost the most, one root cause at a time, and quarantine the rest.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/recipes/flaky-cleanup.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/recipes/flaky-cleanup.html"}],["meta",{"property":"og:title","content":"Flaky Playwright suite: Cut costly flakiness | Piwi"}],["meta",{"property":"og:description","content":"One afternoon to make an unreliable suite trustworthy: fix the flaky tests that cost the most, one root cause at a time, and quarantine the rest."}]]},"headers":[],"relativePath":"recipes/flaky-cleanup.md","filePath":"recipes/flaky-cleanup.md","lastUpdated":1795799473000}'),n={name:"recipes/flaky-cleanup.md"};function i(l,e,h,c,d,u){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="our-suite-is-unreliable-and-i-have-one-afternoon" tabindex="-1">Our suite is unreliable and I have one afternoon <a class="header-anchor" href="#our-suite-is-unreliable-and-i-have-one-afternoon" aria-label="Permalink to &quot;Our suite is unreliable and I have one afternoon&quot;">​</a></h1><p>Flaky-test cleanup usually stalls for the same reason: the list is long, every entry looks equally annoying, and there&#39;s no obvious first move. Ranking by flakiness score doesn&#39;t help much either — a test that flakes constantly but finishes in milliseconds costs almost nothing.</p><p>Rank by what it <em>costs</em> instead, fix three, and leave the rest running.</p><h2 id="_1-work-by-impact-not-by-score" tabindex="-1">1. Work by impact, not by score <a class="header-anchor" href="#_1-work-by-impact-not-by-score" aria-label="Permalink to &quot;1. Work by impact, not by score&quot;">​</a></h2><p>The <strong>Flaky</strong> view of the project&#39;s <strong>Failures</strong> tab gives each test a <a href="/features/flaky-tests.html#flaky-test-detection">flakiness score</a>, but lists the tests by <strong><a href="/features/flaky-tests.html#impact-ranking">impact</a></strong>: what their retries cost in CI minutes.</p><figure><img src="'+t+'" alt="The Flaky view listing intermittent tests with wasted CI minutes, score, failure rate, top suspect, root cause, retry passes or flips and last flake, under root-cause filter chips and a runs-window selector"><figcaption>The Flaky view — ranked by impact, filterable by root cause, over a window of recent runs.</figcaption></figure><p>Start at the top and work down. Each row&#39;s dot colors those minutes, and in a suite carrying real flake debt a few red rows usually account for most of the total.</p><h2 id="_2-filter-by-root-cause-and-fix-a-class-at-once" tabindex="-1">2. Filter by root cause and fix a class at once <a class="header-anchor" href="#_2-filter-by-root-cause-and-fix-a-class-at-once" aria-label="Permalink to &quot;2. Filter by root cause and fix a class at once&quot;">​</a></h2><p>Every flaky test carries a <a href="/features/flaky-tests.html#root-cause-classification">root-cause category</a> (<code>timing</code>, <code>network</code>, <code>assertion</code>, <code>environment</code>, <code>order</code> or <code>other</code>).</p><p>Filtering by category is the trick that makes an afternoon enough, because a class usually shares one fix: eight <code>timing</code> flakes usually share one bad wait helper to replace with a real wait condition, a <code>network</code> class wants a stub or a retry on the fixture rather than the test, and an <code>environment</code> class is a browser-specific guard or a real compatibility bug.</p><h2 id="_3-narrow-the-window-before-you-conclude-anything" tabindex="-1">3. Narrow the window before you conclude anything <a class="header-anchor" href="#_3-narrow-the-window-before-you-conclude-anything" aria-label="Permalink to &quot;3. Narrow the window before you conclude anything&quot;">​</a></h2><p>Two filters change the answer, and both are worth setting deliberately:</p><ul><li><strong>Runs window</strong>: one of the <a href="/features/flaky-tests.html#flaky-test-detection">lookback windows</a>, recent behavior or a longer history. A test fixed last week still looks awful over the longest.</li><li><strong>Environment</strong>: pick one in the project&#39;s <strong>Filters</strong> block and the analysis reads only its runs, so <code>staging</code> noise doesn&#39;t inflate a test that&#39;s stable in <code>production</code>.</li></ul><h2 id="_4-quarantine-the-rest-—-with-an-exit" tabindex="-1">4. Quarantine the rest — with an exit <a class="header-anchor" href="#_4-quarantine-the-rest-—-with-an-exit" aria-label="Permalink to &quot;4. Quarantine the rest — with an exit&quot;">​</a></h2><p>You will not fix them all today, and disabling them is how suites rot. The usual <code>--grep-invert @quarantine</code> approach stops the test running, so nothing ever proves it recovered and the list only grows.</p><p><a href="/features/flaky-tests.html#quarantine-with-a-way-out">Quarantine in Piwi</a> keeps the test running and reporting while it stops blocking merges. Its passes build a streak that flags it <strong>ready to release</strong>, the Flaky view proposes the <strong>candidates</strong> worth quarantining, and the gate can cap how many tests are in, so the list can&#39;t grow unbounded. Promote the proposed candidates, and release the ready ones as they come.</p><h2 id="_5-check-the-fix-held" tabindex="-1">5. Check the fix held <a class="header-anchor" href="#_5-check-the-fix-held" aria-label="Permalink to &quot;5. Check the fix held&quot;">​</a></h2><p>A flaky fix is easy to believe and hard to confirm. Each test case has a <strong>stability trend</strong> — pass rate, flaky rate, and average duration bucketed over time — which is the honest answer to &quot;did that help?&quot;. If the suite-wide picture is what you need, <a href="/features/analytics.html">Analytics</a> lifts the same signals across every project, including wasted CI minutes and a global flaky leaderboard.</p><h2 id="other-ways-in" tabindex="-1">Other ways in <a class="header-anchor" href="#other-ways-in" aria-label="Permalink to &quot;Other ways in&quot;">​</a></h2><p><strong>Ask your agent.</strong> <code>list_flaky_tests</code> over the <a href="/features/mcp.html">MCP server</a> returns each test&#39;s score, impact, wasted CI minutes and root-cause category, highest score first; <code>get_test_stability_trend</code> answers whether one test is getting worse. Useful for &quot;what should I fix this sprint?&quot; without opening a browser.</p><p><strong>Script it.</strong> Quarantine is a REST resource, so promoting candidates or releasing ready tests can be a scheduled job. Shapes are in the <a href="https://piwitests.dev/demo/settings/api" target="_blank" rel="noreferrer">API docs</a>.</p><p><strong>No server at all.</strong> If this is your own laptop suite rather than a team&#39;s, the <a href="/features/desktop.html">desktop app</a> runs the same analysis with no Docker and no Node, on the <a href="/features/desktop.html#where-it-is">systems it is built for</a>, and the installers aren&#39;t signed yet.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/flaky-tests.html">Flaky tests</a> — the full scoring, quarantine, and performance reference</li><li><a href="/features/analytics.html">Analytics</a> — the same signals across every project</li><li><a href="./regression-or-flaky.html">Regression or flake?</a> — deciding whether one red test belongs on this list</li></ul>',24)])])}const g=a(n,[["render",i]]);export{y as __pageData,g as default};
